  "baseline_window": "2025-01-06, 2025-01-13, 2025-01-27",
  "hypotheses": [
    {
      "id": "H0",
      "kind": "metric",
      "statement": "The average total amount per yellow taxi trip on Monday 2025-01-20 was higher than the average of the other Mondays in January 2025 (2025-01-06, 2025-01-13, 2025-01-27).",
      "support_if": "avg_total_amount on 2025-01-20 > baseline average by a meaningful margin (e.g., >5%).",
      "refute_if": "avg_total_amount on 2025-01-20 is within normal variance of baseline Mondays."
    },
    {
      "id": "H1",
      "kind": "holiday",
      "statement": "Monday 2025-01-20 was Martin Luther King Jr. Day (a federal holiday), which altered the fare mix (e.g., more airport/long-distance trips, surge pricing, or different passenger composition) and increased the average total amount.",
      "support_if": "2025-01-20 is flagged as a federal holiday in whybot.us_holidays; baseline Mondays are not holidays.",
      "refute_if": "2025-01-20 is not a holiday, or baseline Mondays also include a holiday."
    },
    {
      "id": "H2",
      "kind": "weather",
      "statement": "Adverse weather on 2025-01-20 (e.g., snow, rain, extreme cold) caused longer trips, higher fares, or a shift to taxi from other modes, raising the average total amount.",
      "support_if": "whybot.nyc_weather_daily shows significant precipitation (prcp_mm > 5 or snow_mm > 0) or extreme temperatures (tmax_c < 0 or tmin_c < -10) on 2025-01-20, while baseline Mondays had mild weather.",
      "refute_if": "Weather on 2025-01-20 was similar to or better than baseline Mondays."
    },
    {
      "id": "H3",
      "kind": "fare_mix",
      "statement": "The composition of trip distances or fare components shifted on 2025-01-20 (e.g., higher avg_trip_distance, more airport trips, tolls, or tips) compared to other Mondays.",
      "support_if": "avg_trip_distance on 2025-01-20 is notably higher than baseline Mondays, or trip count patterns suggest a fare mix change.",
      "refute_if": "avg_trip_distance and trip counts on 2025-01-20 are in line with baseline Mondays."
    },
    {
      "id": "H4",
      "kind": "data_quality",
      "statement": "The spike on 2025-01-20 is due to a data anomaly (e.g., missing trips, duplicate records, or erroneous fare amounts) rather than a real behavioral change.",
      "support_if": "Trip count on 2025-01-20 is unusually low or high vs baseline, or avg_total_amount is an outlier not explained by distance/weather/holiday.",
      "refute_if": "Trip count and avg_trip_distance on 2025-01-20 are consistent with baseline Mondays, and no data-quality flags appear."
    }
  ],
  "queries": [
    {
      "hypothesis_id": "H0",
      "purpose": "Get avg_total_amount, trips, and avg_trip_distance for target Monday 2025-01-20 and baseline Mondays 2025-01-06, 2025-01-13, 2025-01-27 from whybot.yellow_daily.",
      "tables": [
        "whybot.yellow_daily"
      ]
    },
    {
      "hypothesis_id": "H1",
      "purpose": "Check if 2025-01-20 is a federal holiday (Martin Luther King Jr. Day) and baseline Mondays are not, using whybot.us_holidays.",
      "tables": [
        "whybot.us_holidays"
      ]
    },
    {
      "hypothesis_id": "H2",
      "purpose": "Get daily weather (prcp_mm, snow_mm, tmax_c, tmin_c) for 2025-01-20 and baseline Mondays from whybot.nyc_weather_daily.",
      "tables": [
        "whybot.nyc_weather_daily"
      ]
    },
    {
      "hypothesis_id": "H3",
      "purpose": "Compare avg_trip_distance and trips on target vs baseline Mondays to infer fare mix changes (already covered by H0 query; no additional table needed).",
      "tables": [
        "whybot.yellow_daily"
      ]
    },
    {
      "hypothesis_id": "H4",
      "purpose": "Check for data quality issues: trip count outliers or avg_total_amount outliers on target vs baseline Mondays (already covered by H0 query; no additional table needed).",
      "tables": [
        "whybot.yellow_daily"
      ]
    }
  ],
  "rationale": "H0 quantifies the metric jump. H1 tests the federal holiday (MLK Day) which is the most plausible driver for a Monday fare mix shift. H2 tests weather as a confounder. H3 and H4 use the same daily aggregates to check fare mix (distance) and data quality (trip count outliers). All queries are within the 2024-04-01..2025-02-28 window and use only catalog tables."
}

{
